namespace {
void ck(bool b,const std::string& e){if(!b)throw std::runtime_error(e);}
std::vector<std::uint8_t> read(const std::string& p){std::ifstream f(p,std::ios::binary);ck(bool(f),"missing "+p);return {std::istreambuf_iterator<char>(f),{}};}
data::Bytes bytes(const std::vector<std::uint8_t>& b){return {b.data(),b.size()};}
std::string leaf(const std::string& p){return p.substr(p.find_last_of("/\\")+1);}
void finite(const scene::Scene& s){for(const auto& n:s.graph)for(float v:n.world)ck(std::isfinite(v),"nonfinite rendered world matrix");}
}
int main(int argc,char** argv){try{
 ck(argc==2,"assets arg");const std::string a=argv[1];std::string error;
 auto an=read(a+"/data/animations_dictionary_pyarraynames.bin"),av=read(a+"/data/animations_dictionary_pyarray.bin");data::Dictionary clips;ck(data::load_dictionary(bytes(an),bytes(av),clips,error),error);
 auto ar=read(a+"/data/animations_pyarray.bin"),ak=read(a+"/data/animations_pyarraynames.bin"),as=read(a+"/data/animations_pystructnames.bin");data::AnimationTables tables;ck(data::load_animation_tables(bytes(ar),bytes(ak),bytes(as),clips,tables,error),error);
 auto cr=read(a+"/data/character_properties_pyarray.bin"),ckeys=read(a+"/data/character_properties_pyarraynames.bin"),cs=read(a+"/data/character_properties_pystructnames.bin");data::CharacterTable chars;ck(data::load_characters(bytes(cr),bytes(ckeys),bytes(cs),chars,error),error);
