 auto lr=read(a+"/data/loot_table_pyarray.bin"),lk=read(a+"/data/loot_table_pyarraynames.bin"),ls=read(a+"/data/loot_table_pystructnames.bin");data::LootTablesV2 loot;ck(loot.load(bytes(lr),bytes(lk),bytes(ls),error),error);std::array<data::ClassPreviewDefinition,3> defs;ck(data::class_preview_definitions(chars,classes,rules,loot.borrow(),tables,clips,defs,error),error);
 const int rows[]={263,325,290},animtables[]={48,50,49};const char* names[]={"KnightPlayerBase","RoguePlayerBase","MagePlayerBase"};const char* suffix[]={"warrior","rogue","mage"};
 auto model=read(a+"/models/prince_modular.bdae");unsigned preview_modules=0,default_modules=0,samples=0,root_cases=0;std::set<int> required;
 resources::BresView bres{};scene::Scene factory;ck(dh2_bres_open(&bres,model.data(),model.size())==resources::BresError::ok&&scene::load(bres,factory,error),error);ck(factory.graph.size()==35,"Prince graph35");
 auto br=read(a+"/data/prince-animation-bank.bin");data::AnimationBank meta;ck(data::load_animation_bank(bytes(br),meta,error),error);ck(meta.character=="KnightPlayerBase"&&meta.animation_table==48&&meta.resources.size()==116&&meta.registration_requests.size()==158,"Knight receipt boundary");actor::ClipBank bank;
 for(const auto& row:meta.resources){auto raw=read(a+"/"+row.asset);animation::Player p;ck(p.load(raw.data(),raw.size(),factory,error,animation::MissingTargets::ignore),error);bank.emplace(row.clip_id,std::move(p));}
 animation::RegistrationSet registration;for(int id:meta.registration_requests)ck(registration.append(id,data::animation_resource_identity(meta,id),&bank.at(id),error),error);ck(registration.set_default(data::animation_resource_identity(meta,meta.template_clip_id),&bank.at(meta.template_clip_id),error),error);registration.refresh_indices();
 for(unsigned i=0;i<3;++i){const auto& d=defs[i];ck(d.row==rows[i]&&d.animation_table==animtables[i]&&d.character==names[i],"actual player row/property2 mismatch");
  std::vector<std::string> modules{"MC_Head__naked-mesh-skin"};for(const auto& item:d.starting_items)if(item.module.find("MC_Torso_")==0||item.module.find("MC_Feet_")==0||item.module.find("MC_Hands_")==0)modules.push_back(item.module+"-mesh-skin");ck(modules.size()==4,"actual starter4");auto idle=read(a+"/animations/"+leaf(d.idle_clip));objects::Resource preview;ck(objects::load_modular_resource(model.data(),model.size(),modules,idle.data(),idle.size(),preview,error),error);ck(!preview.animation.skipped&&preview.primitives.size()==4,"preview4/unsupported");preview_modules+=preview.primitives.size();ck(objects::sample(preview,preview.animation.start,error)&&objects::sample(preview,preview.animation.end,error),error);finite(preview.scene);samples+=2;
  modules.clear();for(const char* part:{"Head","Torso","Hands","Feet"})modules.push_back(std::string("MC_")+part+"_default_"+suffix[i]+"-mesh-skin");auto game_idle=read(a+"/animations/"+leaf(clips.values.at(1040)));objects::Resource defaults;ck(objects::load_modular_resource(model.data(),model.size(),modules,game_idle.data(),game_idle.size(),defaults,error),error);ck(defaults.primitives.size()==4,"default module4");default_modules+=defaults.primitives.size();ck(objects::sample(defaults,defaults.animation.start,error)&&objects::sample(defaults,defaults.animation.end,error),error);finite(defaults.scene);samples+=2;
  auto live=defaults.scene;visual::SceneBinding visual;ck(visual.bind(live,error),error);actor::BlendedPlayback p;ck(p.compile_dynamic(bank,registration,factory,visual,error),error);data::AnimationRandom random;
  const char* states[]={"Idle","Walk","Run","Attack","AttackStatic","Died","DeadlyGreatKB","Despawn","DespawnGreatKB","IdleSneak","WalkSneak","Template"};
  const unsigned bits[]={2,16,32,64,128,32768,131072,65536,262144,0,0,0};
  for(unsigned n=0;n<12;++n){const auto* base=data::animation_state(tables,d.animation_table,states[n]);ck(base,"source base absent");const int root=int(base-tables.sequences.data());
   for(unsigned stance=0;stance<((210&bits[n])?5u:1u);++stance){const int seq=root+int(stance);++root_cases;
    std::function<void(int,unsigned)> collect=[&](int q,unsigned depth){ck(depth<3,"redirect source limit");for(const auto& st:tables.sequences.at(q).steps)if(st.redir)collect(st.anim,depth+1);else if(st.anim>=0){required.insert(st.anim);ck(bank.count(st.anim)&&p.engine_index(st.anim)>=0,"missing source clip");}};collect(seq,0);
    for(unsigned trial=0;trial<16;++trial){random={trial+1,0};ck(p.start(tables,seq,random,bank,visual,live,1,error),error);ck(p.engine_index(p.current_clip())==p.current_engine_clip(),"game engine mapping");ck(p.scene_phase(1000+samples*17,bank,visual,live,error),error);finite(live);++samples;}
   }
  }
 }
 ck(root_cases==84&&required.size()==80&&preview_modules==12&&default_modules==12,"declared class coverage changed");
 std::cout<<"{\"validation\":\"PASS\",\"classes\":3,\"actual_player_rows\":[263,325,290],\"cached_property2\":[48,50,49],\"base_property_and_loot_definitions\":3,\"preview_modules\":"<<preview_modules<<",\"default_modules\":"<<default_modules<<",\"gameplay_stance_roots\":"<<root_cases<<",\"reachable_gameplay_clips\":"<<required.size()<<",\"bank_resources\":116,\"registration_occurrences\":158,\"real_pose_samples\":"<<samples<<",\"Rogue_Mage_registration_oracle\":false}\n";
 return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
